'''
store memory like {
  "memory_id": "m_001",
  "task_id": "task_001",
  "content": "User prefers budget hotels under 150 AUD per night.",
  "source": "user_history | user_input | tool_observation | agent_summary",
  "created_at": "2026-01-01T10:00:00",
  "last_modified_at": "2026-01-01T10:00:00",
  "last_modified_by": "user_input_1 | step_005", (trace step id or user input id that last modified this memory)
  "derived_from": [], (list of memory ids that this memory is derived from, e.g. if this memory is generated by summarizing two previous memories, then derived_from will contain those two memory ids)
  "supersedes": null, (old memory id that this memory supersedes, e.g. if this memory is an updated version of a previous memory, then supersedes will contain the old memory id)
  "trust_score": 0.90,
  "status": "active | quarantined | deleted | superseded"
}
'''

from copy import deepcopy
from dataclasses import dataclass, asdict, field
from datetime import datetime
from typing import Any, Dict, Iterable, List, Optional, Sequence

from client.model_client import run_embedding


ORACLE_METADATA_FIELDS = (
    "fact_key",
    "fact_value",
    "entity_id",
    "valid_from",
    "valid_to",
    "oracle_role",
)


@dataclass
class Memory:
    """Structured representation of a memory.

    Fields mirror the notes in the repository documentation. Implement
    serialization, validation, and manipulation in the concrete
    implementation.
    """

    memory_id: str
    task_id: str
    content: str
    source: str
    last_modified_by: str
    fault_type: Optional[str] = None
    created_at: datetime = field(default_factory=datetime.now)
    last_modified_at: datetime = field(default_factory=datetime.now)
    derived_from: List[str] = field(default_factory=list)
    supersedes: Optional[str] = None
    trust_score: Optional[float] = None
    status: str = "active"
    fact_key: Optional[str] = None
    fact_value: Optional[Any] = None
    entity_id: Optional[str] = None
    valid_from: Optional[str] = None
    valid_to: Optional[str] = None
    oracle_role: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        """Convert Memory to dictionary for JSON serialization."""
        result = asdict(self)
        # Convert datetime objects to ISO format strings
        if result.get("created_at"):
            result["created_at"] = result["created_at"].isoformat()
        if result.get("last_modified_at"):
            result["last_modified_at"] = result["last_modified_at"].isoformat()
        return result


class MemoryStore:
    """Abstract memory store interface.

    Concrete subclasses should implement persistence, retrieval, and
    querying of memories.
    """
    def __init__(self) -> None:
        """Initialize the memory store."""
        self.memories: Dict[str, Memory] = {}
        self.newest_memory_id: int = 0  # Track the latest memory number for auto-generation
        # Cache of memory_id -> (content, normalized embedding vector). Keyed by
        # content so an edited memory is re-embedded automatically.
        self._embedding_cache: Dict[str, tuple] = {}

    def _extract_memory_number(self, memory_id: str) -> int:
        """Extract the numeric slot from a memory id.

        Handles both the normal form ('m_001' -> 1) and the injected-fault form
        ('m_f006' -> 6). A faulty id carries the numeric slot of the memory it
        stands in for, so advancing ``newest_memory_id`` past it makes the next
        minted memory continue the sequence (m_f006 -> next is m_007) instead of
        colliding on the faulty slot.
        """
        try:
            # Handle 'm_001' and the faulty 'm_f006' form.
            if memory_id.startswith('m_'):
                suffix = memory_id[2:]
                if suffix.startswith('f'):
                    suffix = suffix[1:]
                return int(suffix)
            return 0
        except (ValueError, IndexError):
            return 0

    def _generate_memory_id(self) -> str:
        """Generate the next memory_id in sequence."""
        self.newest_memory_id += 1
        return f"m_{self.newest_memory_id:03d}"

    def add_memory(self, memory: Optional[Memory] = None, **kwargs) -> str:
        """Add a memory and return its `memory_id`.
        
        Args:
            memory: Memory object to add. If provided, kwargs are ignored.
            **kwargs: If memory not provided, create Memory from kwargs (auto-generates memory_id).
        
        Returns:
            The memory_id of the added memory.
        """
        memory_id = self._generate_memory_id()
        
        if memory is None:
            memory = Memory()
        
        memory.memory_id =  memory_id
        self.memories[memory.memory_id] = memory
        return memory_id

    def get_memory(self, memory_id: str) -> Optional[Memory]:
        """Return a Memory by id or ``None`` if not found."""
        return self.memories.get(memory_id)

    def update_memory(self, memory_id: str, updates: Dict[str, Any]) -> str:
        """Create a new memory with updates and mark original as superseded.
        
        Returns the new memory_id.
        """
        memory = self.get_memory(memory_id)
        if memory is None:
            raise KeyError(f"Memory not found: {memory_id}")

        # Prevent updating memory_id
        if "memory_id" in updates:
            raise ValueError("Cannot update memory_id")

        # Validate all update fields
        for field_name in updates.keys():
            if not hasattr(memory, field_name):
                raise ValueError(f"Unknown memory field: {field_name}")

        new_memory_id = self._generate_memory_id()
        # Create new memory from original, applying updates
        new_memory_dict = asdict(deepcopy(memory))
        new_memory_dict.update(updates)
        new_memory_dict["memory_id"] = new_memory_id
        new_memory_dict["supersedes"] = memory_id
        new_memory_dict["status"] = "active"
        new_memory_dict["last_modified_at"] = datetime.now()
        
        # Mark original as superseded
        memory.status = "superseded"
        memory.last_modified_at = datetime.now()
        
        # Create and add new memory
        new_memory = Memory(**new_memory_dict)
        self.memories[new_memory_id] = new_memory
        
        return new_memory_id

    def delete_memory(self, memory_id: str) -> None:
        """Mark or remove a memory from the store."""
        memory = self.get_memory(memory_id)
        if memory is None:
            raise KeyError(f"Memory not found: {memory_id}")
        memory.status = "deleted"
        memory.last_modified_at = datetime.now()

    def consolidate_memories(
        self,
        source_ids: Sequence[str],
        content: str,
        source: str = "agent_summary",
        trust_score: Optional[float] = None,
        last_modified_by: str = "agent",
    ) -> str:
        """Summarize two or more memories into a single new memory.

        Creates a new active memory whose ``derived_from`` lists ``source_ids``
        and marks each source memory as ``superseded``. Returns the new
        ``memory_id``. Requires at least two distinct, existing source ids.
        """
        unique_ids = list(dict.fromkeys(source_ids))
        if len(unique_ids) < 2:
            raise ValueError("consolidate_memories requires at least two source ids")

        sources: List[Memory] = []
        for source_id in unique_ids:
            memory = self.get_memory(source_id)
            if memory is None:
                raise KeyError(f"Memory not found: {source_id}")
            sources.append(memory)

        new_memory = Memory(
            memory_id="",  # assigned by the store
            task_id=sources[0].task_id,
            content=content,
            source=source,
            last_modified_by=last_modified_by,
            derived_from=unique_ids,
            trust_score=trust_score,
            status="active",
        )
        for field_name in ORACLE_METADATA_FIELDS:
            values = [
                getattr(memory, field_name)
                for memory in sources
                if getattr(memory, field_name) is not None
            ]
            if values and all(value == values[0] for value in values):
                setattr(new_memory, field_name, values[0])
        new_id = self.add_memory(new_memory)

        # The summary now stands in for its sources; retire them.
        for memory in sources:
            memory.status = "superseded"
            memory.last_modified_at = datetime.now()

        return new_id

    def _embed_memories(self, memories: List[Memory]) -> Dict[str, List[float]]:
        """Return normalized embeddings for `memories`, using the cache.

        Memories whose content is unchanged reuse the cached vector. Any new or
        edited content is embedded in a single batched call.
        """
        vectors: Dict[str, List[float]] = {}
        to_embed: List[Memory] = []
        for memory in memories:
            cached = self._embedding_cache.get(memory.memory_id)
            if cached is not None and cached[0] == memory.content:
                vectors[memory.memory_id] = cached[1]
            else:
                to_embed.append(memory)

        if to_embed:
            embeddings = run_embedding([m.content for m in to_embed], normalize=True)
            # run_embedding returns a single vector for one input; normalize shape.
            if to_embed and isinstance(embeddings[0], (int, float)):
                embeddings = [embeddings]
            for memory, vector in zip(to_embed, embeddings):
                self._embedding_cache[memory.memory_id] = (memory.content, vector)
                vectors[memory.memory_id] = vector

        return vectors

    @staticmethod
    def _cosine_similarity(a: Sequence[float], b: Sequence[float]) -> float:
        """Dot product of two vectors (cosine similarity when both normalized)."""
        return sum(x * y for x, y in zip(a, b))

    def find_relevant_memories(
        self, query: str, limit: int = 10, task_id: Optional[str] = None
    ) -> List[Memory]:
        """Return memories most relevant to `query`, ranked by embedding similarity.

        Active memories (optionally filtered by `task_id`) are embedded with the
        configured embedding model and ranked by cosine similarity to the query
        embedding, breaking ties by recency. If embedding fails (e.g. no API key
        or network access), falls back to returning the most recent memories.
        """
        memories = [m for m in self.memories.values() if m.status == "active"]
        if task_id is not None:
            memories = [m for m in memories if m.task_id == task_id]
        if not memories:
            return []

        try:
            query_vector = run_embedding(query, normalize=True)
            memory_vectors = self._embed_memories(memories)
        except Exception:
            # Fall back to recency ordering when embeddings are unavailable.
            memories.sort(key=lambda memory: memory.created_at, reverse=True)
            return memories[:limit]

        def score(memory: Memory) -> tuple:
            vector = memory_vectors.get(memory.memory_id)
            similarity = self._cosine_similarity(query_vector, vector) if vector else -1.0
            return (similarity, memory.created_at)

        memories.sort(key=score, reverse=True)
        return memories[:limit]

    def list_memories(self, task_id: Optional[str] = None) -> Iterable[Memory]:
        """Yield all memories, optionally filtered by `task_id`."""
        for memory in self.memories.values():
            if task_id is None or memory.task_id == task_id:
                yield memory

    def deserialize(self, data: Dict[str, Any]) -> Memory:
        """Create a ``Memory`` from a dict representation."""
        created_at = data.get("created_at")
        if isinstance(created_at, str):
            created_at = datetime.fromisoformat(created_at)

        last_modified_at = data.get("last_modified_at")
        if isinstance(last_modified_at, str):
            last_modified_at = datetime.fromisoformat(last_modified_at)

        memory = Memory(
            memory_id=data["memory_id"],
            task_id=data["task_id"],
            content=data["content"],
            source=data["source"],
            last_modified_by=data.get("last_modified_by", "unknown"),
            fault_type=data.get("fault_type"),
            created_at=created_at or datetime.now(),
            last_modified_at=last_modified_at or datetime.now(),
            derived_from=data.get("derived_from", []),
            supersedes=data.get("supersedes"),
            trust_score=data.get("trust_score"),
            status=data.get("status", "active"),
            fact_key=data.get("fact_key"),
            fact_value=data.get("fact_value"),
            entity_id=data.get("entity_id"),
            valid_from=data.get("valid_from"),
            valid_to=data.get("valid_to"),
            oracle_role=data.get("oracle_role"),
        )
        # Update newest_memory_id if this memory's number is higher
        num = self._extract_memory_number(memory.memory_id)
        if num > self.newest_memory_id:
            self.newest_memory_id = num
        return memory

    def load_memories(self, data: Iterable[Dict[str, Any]]) -> None:
        """Restore serialized memories into the store, preserving their ids.

        Unlike :meth:`add_memory`, this keeps each memory's existing
        ``memory_id`` so a session's accumulated state can be restored before
        responding to a new turn. ``deserialize`` advances ``newest_memory_id``
        past the highest loaded id so memories added afterwards don't collide.
        """
        for item in data:
            memory = self.deserialize(item)
            self.memories[memory.memory_id] = memory

    def get_memories(self) -> List[Dict[str, Any]]:
        """Return all memories in the store."""
        return [memory.to_dict() for memory in self.memories.values()]
